import { test, expect } from '@playwright/test';

test.describe('Form Auto-Save as Draft', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/form');
  });

  test('should auto-save form as draft every 30 seconds when user makes changes', async ({ page }) => {
    // Verify form is visible
    const form = page.getByRole('form');
    await expect(form).toBeVisible();

    // Verify draft status is not initially set
    const draftStatus = page.getByText('Draft');
    await expect(draftStatus).not.toBeVisible();

    // Get form fields using getByLabel
    const nameField = page.getByLabel('Full Name');
    const emailField = page.getByLabel('Email Address');
    const messageField = page.getByLabel('Message');

    // Type in form fields
    await nameField.fill('John Doe');
    await emailField.fill('john@example.com');
    await messageField.fill('This is a test message for auto-save.');

    // Wait for the first auto-save to occur (should be within 30 seconds)
    await page.waitForTimeout(35000);

    // Verify draft status appears
    await expect(draftStatus).toBeVisible();
    await expect(draftStatus).toContainText('Draft');

    // Verify save message appears
    const saveMessage = page.getByText('Draft saved successfully');
    await expect(saveMessage).toBeVisible();

    // Verify draft status persists after another change
    await messageField.fill('This is an updated test message.');
    await page.waitForTimeout(35000);
    await expect(draftStatus).toBeVisible();
    await expect(draftStatus).toContainText('Draft');
    await expect(saveMessage).toBeVisible();
  });

  test('should not auto-save when form is empty or user does not interact with fields', async ({ page }) => {
    // Verify form is visible
    const form = page.getByRole('form');
    await expect(form).toBeVisible();

    // Verify draft status is not visible when form is empty
    const draftStatus = page.getByText('Draft');
    await expect(draftStatus).not.toBeVisible();

    // Verify save message is not visible when form is empty
    const saveMessage = page.getByText('Draft saved successfully');
    await expect(saveMessage).not.toBeVisible();

    // Wait for the auto-save interval (should not trigger)
    await page.waitForTimeout(35000);

    // Verify draft status is still not visible
    await expect(draftStatus).not.toBeVisible();

    // Verify save message is still not visible
    await expect(saveMessage).not.toBeVisible();

    // Verify form fields are empty
    const nameField = page.getByLabel('Full Name');
    const emailField = page.getByLabel('Email Address');
    const messageField = page.getByLabel('Message');
    await expect(nameField).toHaveValue('');
    await expect(emailField).toHaveValue('');
    await expect(messageField).toHaveValue('');
  });
});
